  const groups=visual.groups??[],notes=sequence.notes??[],expectedIds=new Set<string>(['visual-title']);for(let i=0;i<participants.length;i++){const id='p'+(i+1);expectedIds.add(id);expectedIds.add(id+'-lifeline');for(const field of ['detail','role','status'] as const)if(participants[i]![field]!==undefined)expectedIds.add(id+'-'+field);if(participants[i]!.icon!==undefined)expectedIds.add(id+'-icon');}for(let i=0;i<messages.length;i++){expectedIds.add('message'+(i+1));expectedIds.add('message-caption'+(i+1));}for(let i=0;i<groups.length;i++)expectedIds.add('f'+(i+1));for(let i=0;i<notes.length;i++)expectedIds.add('n'+(i+1));
