  exactMap('visual-title','visual',visual.id,sourcePath('/id'));const titleBlock=byId.get('visual-title')??[];if(titleBlock.length!==1||titleBlock[0]?.selector!=='rect'||!linesMatch(visual.title??visual.question,titleBlock[0]?.label?titleBlock[0].label.split('\n'):[])){nativeOk=false;problems.push('Sequence title native text carrier does not preserve the authored title.');}
